#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Define a struct to represent a Roman numeral
typedef struct {
    char *symbol;
    int value;
} RomanNumeral;

// Define an array of Roman numerals
RomanNumeral romanNumerals[] = {
    {"M", 1000},
    {"CM", 900},
    {"D", 500},
    {"CD", 400},
    {"C", 100},
    {"XC", 90},
    {"L", 50},
    {"XL", 40},
    {"X", 10},
    {"IX", 9},
    {"V", 5},
    {"IV", 4},
    {"I", 1}
};

// Function to convert a Roman numeral to an integer
int romanToInt(char *romanNumeral) {
    int result = 0;
    int i = 0;
    while (*romanNumeral != '\0') {
        // Check if the current numeral is a valid Roman numeral
        if (strncmp(romanNumeral, romanNumerals[i].symbol, strlen(romanNumerals[i].symbol)) == 0) {
            // Add the value of the current numeral to the result
            result += romanNumerals[i].value;
            // Move to the next numeral
            romanNumeral += strlen(romanNumerals[i].symbol);
        } else {
            // If the current numeral is not valid, print an error message and return 0
            printf("INVALID\n");
            return 0;
        }
        i = (i + 1) % 13;
    }
    return result;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <Roman numeral>\n", argv[0]);
        return 1;
    }
    int result = romanToInt(argv[1]);
    if (result != 0) {
        printf("%d\n", result);
    }
    return 0;
}
